    50  struct postV2Tail
    51  {
    52    friend struct post;
    53
    54    bool sanitize (hb_sanitize_context_t *c) const
    55    {
    56      TRACE_SANITIZE (this);
    57      return_trace (glyphNameIndex.sanitize (c));
    58    }
    59
    60    protected:
    61    ArrayOf<HBUINT16>     glyphNameIndex; /* This is not an offset, but is the
    62                                           * ordinal number of the glyph in 'post'
    63                                           * string tables. */
    64  /*UnsizedArrayOf<HBUINT8>
    65                          namesX;*/       /* Glyph names with length bytes [variable]
    66                                           * (a Pascal string). */
    67
    68    public:
    69    DEFINE_SIZE_ARRAY (2, glyphNameIndex);
    70  };
    71
    72  struct post
    73  {
    74    enum { tableTag = HB_OT_TAG_post };
    75
    76    bool subset (hb_subset_plan_t *plan) const
    77    {
    78      unsigned int post_prime_length;
    79      hb_blob_t *post_blob = hb_sanitize_context_t ().reference_table<post>(plan->source);
    80      hb_blob_t *post_prime_blob = hb_blob_create_sub_blob (post_blob, 0, post::min_size);
    81      post *post_prime = (post *) hb_blob_get_data_writable (post_prime_blob, &post_prime_length);
    82      hb_blob_destroy (post_blob);
    83
    84      if (unlikely (!post_prime || post_prime_length != post::min_size))
    85      {
    86        hb_blob_destroy (post_prime_blob);
    87        DEBUG_MSG(SUBSET, nullptr, "Invalid source post table with length %d.", post_prime_length);
    88        return false;
    89      }
    90
    91      post_prime->version.major.set (3); // Version 3 does not have any glyph names.
    92      bool result = plan->add_table (HB_OT_TAG_post, post_prime_blob);
    93      hb_blob_destroy (post_prime_blob);
    94
    95      return result;
    96    }
    97
    98    struct accelerator_t
    99    {
   100      void init (hb_face_t *face)
   101      {
   102        index_to_offset.init ();
   103
   104        table = hb_sanitize_context_t ().reference_table<post> (face);
   105        unsigned int table_length = table.get_length ();
   106
   107        version = table->version.to_int ();
   108        if (version != 0x00020000) return;
   109
   110        const postV2Tail &v2 = table->v2X;
   111
   112        glyphNameIndex = &v2.glyphNameIndex;
   113        pool = &StructAfter<uint8_t> (v2.glyphNameIndex);
   114
   115        const uint8_t *end = (const uint8_t *) (const void *) table + table_length;
   116        for (const uint8_t *data = pool;
   117             index_to_offset.len < 65535 && data < end && data + *data < end;
   118             data += 1 + *data)
   119          index_to_offset.push (data - pool);
   120      }
   121      void fini ()
   122      {
   123        index_to_offset.fini ();
   124        free (gids_sorted_by_name.get ());
   125        table.destroy ();
   126      }
   127
   128      bool get_glyph_name (hb_codepoint_t glyph,
   129                           char *buf, unsigned int buf_len) const
   130      {
   131        hb_bytes_t s = find_glyph_name (glyph);
   132        if (!s.len) return false;
   133        if (!buf_len) return true;
   134        unsigned int len = MIN (buf_len - 1, s.len);
   135        strncpy (buf, s.arrayZ, len);
   136        buf[len] = '\0';
   137        return true;
   138      }
   139
   140      bool get_glyph_from_name (const char *name, int len,
   141                                hb_codepoint_t *glyph) const
   142      {
   143        unsigned int count = get_glyph_count ();
   144        if (unlikely (!count)) return false;
   145
   146        if (len < 0) len = strlen (name);
   147
   148        if (unlikely (!len)) return false;
   149
   150      retry:
   151        uint16_t *gids = gids_sorted_by_name.get ();
   152
   153        if (unlikely (!gids))
   154        {
   155          gids = (uint16_t *) malloc (count * sizeof (gids[0]));
   156          if (unlikely (!gids))
   157            return false; /* Anything better?! */
   158
   159          for (unsigned int i = 0; i < count; i++)
   160            gids[i] = i;
   161          hb_sort_r (gids, count, sizeof (gids[0]), cmp_gids, (void *) this);
   162
   163          if (unlikely (!gids_sorted_by_name.cmpexch (nullptr, gids)))
   164          {
   165            free (gids);
   166            goto retry;
   167          }
   168        }
   169
   170        hb_bytes_t st (name, len);
   171        const uint16_t *gid = (const uint16_t *) hb_bsearch_r (&st, gids, count, sizeof (gids[0]), cmp_key, (void *) this);
   172        if (gid)
   173        {
   174          *glyph = *gid;
   175          return true;
   176        }
   177
   178        return false;
   179      }
   180
   181      protected:
   182
   183      unsigned int get_glyph_count () const
   184      {
   185        if (version == 0x00010000)
   186          return NUM_FORMAT1_NAMES;
   187
   188        if (version == 0x00020000)
   189          return glyphNameIndex->len;
   190
   191        return 0;
   192      }
   193
   194      static int cmp_gids (const void *pa, const void *pb, void *arg)
   195      {
   196        const accelerator_t *thiz = (const accelerator_t *) arg;
   197        uint16_t a = * (const uint16_t *) pa;
   198        uint16_t b = * (const uint16_t *) pb;
   199        return thiz->find_glyph_name (b).cmp (thiz->find_glyph_name (a));
   200      }
   201
   202      static int cmp_key (const void *pk, const void *po, void *arg)
   203      {
   204        const accelerator_t *thiz = (const accelerator_t *) arg;
   205        const hb_bytes_t *key = (const hb_bytes_t *) pk;
   206        uint16_t o = * (const uint16_t *) po;
   207        return thiz->find_glyph_name (o).cmp (*key);
   208      }
   209
   210      hb_bytes_t find_glyph_name (hb_codepoint_t glyph) const
   211      {
   212        if (version == 0x00010000)
   213        {
   214          if (glyph >= NUM_FORMAT1_NAMES)
   215            return hb_bytes_t ();
   216
   217          return format1_names (glyph);
   218        }
   219
   220        if (version != 0x00020000 || glyph >= glyphNameIndex->len)
   221          return hb_bytes_t ();
   222
   223        unsigned int index = glyphNameIndex->arrayZ[glyph];
   224        if (index < NUM_FORMAT1_NAMES)
   225          return format1_names (index);
   226        index -= NUM_FORMAT1_NAMES;
   227
   228        if (index >= index_to_offset.len)
   229          return hb_bytes_t ();
   230        unsigned int offset = index_to_offset[index];
   231
   232        const uint8_t *data = pool + offset;
   233        unsigned int name_length = *data;
   234        data++;
   235
   236        return hb_bytes_t ((const char *) data, name_length);
   237      }
   238
   239      private:
   240      hb_blob_ptr_t<post> table;
   241      uint32_t version;
   242      const ArrayOf<HBUINT16> *glyphNameIndex;
   243      hb_vector_t<uint32_t, 1> index_to_offset;
   244      const uint8_t *pool;
   245      hb_atomic_ptr_t<uint16_t *> gids_sorted_by_name;
   246    };
   247
   248    bool sanitize (hb_sanitize_context_t *c) const
   249    {
   250      TRACE_SANITIZE (this);
   251      return_trace (likely (c->check_struct (this) &&
   252                            (version.to_int () == 0x00010000 ||
   253                             (version.to_int () == 0x00020000 && v2X.sanitize (c)) ||
   254                             version.to_int () == 0x00030000)));
   255    }
   256
   257    public:
   258    FixedVersion<>version;                /* 0x00010000 for version 1.0
   259                                           * 0x00020000 for version 2.0
   260                                           * 0x00025000 for version 2.5 (deprecated)
   261                                           * 0x00030000 for version 3.0 */
   262    Fixed         italicAngle;            /* Italic angle in counter-clockwise degrees
   263                                           * from the vertical. Zero for upright text,
   264                                           * negative for text that leans to the right
   265                                           * (forward). */
   266    FWORD         underlinePosition;      /* This is the suggested distance of the top
   267                                           * of the underline from the baseline
   268                                           * (negative values indicate below baseline).
   269                                           * The PostScript definition of this FontInfo
   270                                           * dictionary key (the y coordinate of the
   271                                           * center of the stroke) is not used for
   272                                           * historical reasons. The value of the
   273                                           * PostScript key may be calculated by
   274                                           * subtracting half the underlineThickness
   275                                           * from the value of this field. */
   276    FWORD         underlineThickness;     /* Suggested values for the underline
   277                                             thickness. */
   278    HBUINT32      isFixedPitch;           /* Set to 0 if the font is proportionally
   279                                           * spaced, non-zero if the font is not
   280                                           * proportionally spaced (i.e. monospaced). */
   281    HBUINT32      minMemType42;           /* Minimum memory usage when an OpenType font
   282                                           * is downloaded. */
   283    HBUINT32      maxMemType42;           /* Maximum memory usage when an OpenType font
   284                                           * is downloaded. */
   285    HBUINT32      minMemType1;            /* Minimum memory usage when an OpenType font
   286                                           * is downloaded as a Type 1 font. */
   287    HBUINT32      maxMemType1;            /* Maximum memory usage when an OpenType font
   288                                           * is downloaded as a Type 1 font. */
   289    postV2Tail    v2X;
   290    DEFINE_SIZE_MIN (32);
   291  };
